import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_COSECHA, MODELO_GRANJA, TABLA_COSECHAS } from '../../models/granja-cosecha.model.mjs';

export async function crearCosechaRepository(cosecha) {
  await MODELO_COSECHA.build(PutItemCommand)
    .item(cosecha)
    .options({ condition: { attr: 'cosechaId', exists: false } })
    .send();
}

export async function listarCosechasRepository() {
  const { Items = [] } = await TABLA_COSECHAS.build(ScanCommand)
    .entities(MODELO_COSECHA)
    .options({ consistent: true })
    .send();
  return Items;
}

