export async function buscarGranjaRepository(granjaId) {
  const { Item } = await MODELO_GRANJA.build(GetItemCommand)
    .key({ granjaId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarGranjaRepository(granjaId, minimo) {
  const { Items = [] } = await TABLA_COSECHAS.build(QueryCommand)
    .entities(MODELO_COSECHA)
    .query({ index: 'PorGranja', partition: granjaId })
    .options({ filters: { Cosecha: { attr: 'kilos', gte: minimo } } })
    .send();
  return Items;
}

